import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours annuel CM2 : consolidation des acquis et préparation à la 6e.
class Cm2CompletionScreen extends StatelessWidget {
 const Cm2CompletionScreen({super.key});
 static const _units=<_Unit>[
    _Unit('T1 • Français','Lecture, inférences et résumé','Je lis attentivement et distingue les informations explicites des indices qui permettent de déduire une information. Pour résumer, je garde les idées essentielles et respecte l’ordre du texte. Avant de répondre, je repère le narrateur, les personnages, le lieu, le moment et le problème. Je justifie chaque inférence par un indice précis du texte. Pour résumer, je supprime les répétitions et les détails secondaires sans ajouter mon opinion.','Un personnage ferme les fenêtres, range les objets et attache les volets. On peut déduire qu’un vent violent approche.','Que peut-on déduire de ses gestes ?',['Il prépare la maison au mauvais temps','Il prépare un repas','Il part à la pêche'],0,'Il protège la maison contre le vent.'),
    _Unit('T1 • Mathématiques','Numération, opérations et problèmes','Je maîtrise les nombres entiers, les quatre opérations et le choix de l’opération adaptée à un problème. J’estime le résultat avant le calcul pour repérer une erreur. Je décompose les nombres en milliers, centaines, dizaines et unités. Dans un problème à plusieurs étapes, je note les calculs dans l’ordre, j’écris l’unité et je contrôle le résultat par estimation ou opération inverse.','Une école reçoit 24 cartons de 36 cahiers : 24 × 36 = 864 cahiers.','Une coopérative partage 945 graines entre 9 groupes. Combien chaque groupe reçoit-il ?',['95','105','115'],1,'945 ÷ 9 = 105.'),
    _Unit('T1 • Anglais','Communication et présent simple','Je parle de mes habitudes, de ma famille et de mon école. Au présent simple, he/she/it prend généralement -s ou -es ; les questions utilisent do ou does. Je révise les pronoms sujets, les adjectifs possessifs (my, your, his, her) et les expressions de fréquence (always, often, sometimes, never). Après does ou doesn’t, le verbe revient à sa forme de base.','Does your brother play football? — Yes, he does.','Complète : My mother … in a hospital.',['work','works','working'],1,'Avec my mother (she), on ajoute -s : works.'),
    _Unit('T1 • Sciences','Respiration, circulation et santé','La respiration apporte du dioxygène à l’organisme et rejette du dioxyde de carbone. Le cœur propulse le sang dans les vaisseaux. L’activité physique adaptée et l’hygiène soutiennent la santé. L’air entre par les voies respiratoires jusqu’aux poumons où se réalisent des échanges gazeux. Le sang transporte le dioxygène vers les organes. Le repos, l’eau, l’activité physique et l’absence de fumée protègent l’organisme.','Pendant un effort, le cœur bat plus vite et la respiration s’accélère.','Quel organe propulse le sang ?',['Le cœur','L’estomac','Le rein'],0,'Le cœur agit comme une pompe qui fait circuler le sang.'),
    _Unit('T1 • Éducation sociale','Cartes, territoires et repères historiques','Je lis une carte avec son titre, sa légende, son échelle et son orientation. Je situe des lieux et j’organise les événements historiques sur une ligne du temps. Je distingue les points cardinaux et utilise la légende pour interpréter les symboles. Sur une frise, une date ancienne se place avant une date récente. Je compare les sources et évite de confondre un fait historique avec une opinion.','Une échelle indique le rapport entre une distance sur la carte et la distance réelle.','À quoi sert l’échelle d’une carte ?',['À mesurer les distances représentées','À donner la météo','À nommer les habitants'],0,'L’échelle permet de convertir une distance sur la carte en distance réelle.'),
    _Unit('T2 • Français','Grammaire, accords et fonctions','Je distingue sujet, verbe, compléments et expansions du nom. J’accorde le verbe avec son sujet et l’adjectif avec le nom auquel il se rapporte. Pour trouver le sujet, j’encadre le groupe verbal puis je pose « qui est-ce qui ? ». Je distingue le COD, directement relié au verbe, du COI introduit par une préposition. Je vérifie les accords en changeant le nombre du sujet ou du nom.','« Les grandes cases colorées bordent la route. » Grandes et colorées s’accordent avec cases.','Choisis la forme correcte : Les enfants … leurs leçons.',['révise','révisent','révisons'],1,'Le sujet pluriel les enfants commande révisent.'),
    _Unit('T2 • Mathématiques','Fractions, décimaux et proportionnalité','Une fraction peut représenter un partage ou un quotient. Pour calculer une fraction simple d’une quantité, je partage selon le dénominateur puis je prends le nombre de parts indiqué. La proportionnalité conserve le même coefficient. Je simplifie une fraction en divisant numérateur et dénominateur par un même nombre non nul. Dans un tableau de proportionnalité, je multiplie ou divise les deux lignes par le même coefficient. Je vérifie les unités dans les problèmes de prix, quantité et durée.','Les 3/4 de 20 = 20 ÷ 4 × 3 = 15.','Les 2/5 de 30 valent combien ?',['10','12','15'],1,'30 ÷ 5 × 2 = 12.'),
    _Unit('T2 • Anglais','Prétérit et récit d’événements','Le prétérit décrit une action achevée dans le passé. Les verbes réguliers prennent souvent -ed ; les verbes irréguliers ont une forme propre. Did sert dans les questions et did not dans les négations. Je mémorise les formes irrégulières fréquentes et les marqueurs yesterday, last..., ago. Avec did/didn’t, j’utilise toujours la base verbale : Did she go? She didn’t go.','We visited the museum yesterday. Did you see the animals?','Choisis le prétérit de « go ».',['goed','went','going'],1,'Go est irrégulier : son prétérit est went.'),
    _Unit('T2 • Sciences','Électricité, circuits et transformations d’énergie','Un circuit fermé permet au courant de circuler. Une pile fournit de l’énergie électrique ; un récepteur la transforme. Il faut respecter les règles de sécurité et ne jamais manipuler le secteur sans adulte qualifié. Je reconnais générateur, fils conducteurs, récepteur et interrupteur. Un circuit ouvert ne laisse pas circuler le courant. Je réalise uniquement des montages scolaires à basse tension avec le matériel prévu, jamais une prise domestique.','Une lampe transforme l’énergie électrique en lumière et en chaleur.','Quel élément ouvre ou ferme un circuit ?',['Un interrupteur','Une règle','Un verre'],0,'L’interrupteur commande l’ouverture et la fermeture du circuit.'),
    _Unit('T2 • Éducation sociale','Institutions, citoyenneté et solidarité','Les institutions assurent l’organisation de la vie publique. La citoyenneté implique droits, devoirs, participation et respect des différences. La solidarité aide les personnes et renforce la communauté. Je distingue les règles de la classe, de la commune et de l’État. Un désaccord se règle par le dialogue, l’écoute et des arguments respectueux. Je protège les biens publics et je participe aux actions utiles à la communauté.','Participer à une action de nettoyage du quartier est un engagement collectif.','Quel acte montre la solidarité ?',['Aider une personne en difficulté','Se moquer d’elle','Détruire le matériel collectif'],0,'Aider une personne en difficulté est un geste solidaire.'),
    _Unit('T3 • Français','Conjugaison, orthographe et rédaction','Je choisis les temps adaptés au récit, vérifie les accords et organise un texte en paragraphes. Une rédaction comprend une situation de départ, des événements ordonnés et une conclusion. Avant d’écrire, je prépare un plan et une liste de mots utiles. Après le premier jet, je relis dans cet ordre : sens et enchaînement, phrases et ponctuation, accords, orthographe. Chaque paragraphe développe une idée.','Connecteurs : d’abord, ensuite, cependant, enfin. Ils rendent le texte cohérent.','Quel connecteur annonce la dernière étape ?',['D’abord','Enfin','Parce que'],1,'Enfin annonce la dernière étape.'),
    _Unit('T3 • Mathématiques','Mesures, géométrie et résolution de problèmes','Je calcule périmètres et aires, convertis les unités et reconnais les propriétés des figures. Pour un rectangle, l’aire est longueur × largeur ; le périmètre est deux fois la somme des côtés différents. Je convertis les longueurs en utilisant les rapports de 10 et les aires en utilisant les rapports de 100 entre unités carrées voisines. Je distingue toujours longueur, périmètre et aire et j’écris cm² ou m² pour une surface.','Un rectangle de 12 m sur 5 m a une aire de 60 m² et un périmètre de 34 m.','Quel est le périmètre d’un carré de côté 7 cm ?',['14 cm','28 cm','49 cm'],1,'P = 4 × 7 = 28 cm.'),
    _Unit('T3 • Anglais','Futur, conseils et expression','Will exprime une action future ou une prédiction. Should sert à donner un conseil. Je construis des phrases simples et réponds à des questions sur des projets. Je forme les questions avec Will + sujet + verbe ? et les conseils avec You should + base verbale. Je présente un projet en précisant le moment, le lieu et deux actions prévues.','You should drink clean water. I will visit my cousin tomorrow.','Que signifie « should » dans un conseil ?',['Devoir / il serait bon de','Hier','Jamais'],0,'Should sert à recommander une action.'),
    _Unit('T3 • Sciences','Environnement, sols et ressources naturelles','Le sol abrite des êtres vivants et permet aux plantes de pousser. L’érosion emporte les particules du sol. Planter des arbres, limiter les feux et gérer les déchets protègent l’environnement. La couverture végétale protège le sol contre le ruissellement et le vent. Le compost enrichit la terre ; le tri et la réduction des déchets limitent la pollution. J’identifie les ressources renouvelables et les gestes d’économie d’eau.','Les racines retiennent une partie du sol et réduisent son emport par l’eau.','Quel geste limite l’érosion ?',['Déboiser les pentes','Planter des arbres','Brûler toute la végétation'],1,'Les racines aident à stabiliser le sol.'),
    _Unit('T3 • Éducation sociale','Révision générale et préparation à la 6e','Je consolide les connaissances, lis les consignes jusqu’au bout, présente un travail soigné et justifie mes réponses. Je respecte les autres et prends soin des biens communs. Je prépare l’entrée en 6e avec un planning de révision, des exercices variés et une correction attentive des erreurs. Le jour d’une évaluation, je répartis le temps, commence par les questions comprises et relis toutes mes réponses.','Pour résoudre un problème, je repère les données, la question, l’opération et je vérifie le résultat.','Quelle méthode aide à résoudre un problème ?',['Choisir une opération au hasard','Repérer données et question puis vérifier','Ne pas lire l’énoncé'],1,'Comprendre les données et vérifier le résultat rend la démarche fiable.'),
 ];
 static int get unitCount=>_units.length;
 static int get lessonCount=>_units.length;
 static List<Exercise> assessmentExercisesForTerm(int term,{String? subjectName}){final prefix='T$term •';final result=<Exercise>[];for(var i=0;i<_units.length;i++){final u=_units[i];if(!u.title.startsWith(prefix))continue;if(subjectName!=null&&!_matches(u.title,subjectName))continue;result.add(Exercise(id:'cm2_t${term}_u${i}',lessonId:'cm2_t${term}_u${i}',question:u.question,options:u.options,correctIndex:u.answer,explanation:u.explanation));}return result;}
 static bool _matches(String title,String subject){final t=title.toLowerCase(),s=subject.toLowerCase();if(s.contains('français')||s.contains('francais'))return t.contains('français');if(s.contains('math'))return t.contains('mathématiques');if(s.contains('anglais')||s.contains('english'))return t.contains('anglais');if(s.contains('science'))return t.contains('sciences');if(s.contains('social')||s.contains('civique')||s.contains('morale')||s.contains('histoire')||s.contains('géographie'))return t.contains('éducation sociale');return false;}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Complément CM2 • Année complète')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('${Cm2CompletionScreen.unitCount} unités • ${Cm2CompletionScreen.lessonCount} leçons • 3 trimestres\nLis le cours, étudie l’exemple, réponds puis consulte la correction.',style:const TextStyle(fontWeight:FontWeight.w600)))),for(final u in _units)_UnitTile(unit:u)]));
}
class _Unit{final String title,objective,content,example,question;final List<String> options;final int answer;final String explanation;const _Unit(this.title,this.objective,this.content,this.example,this.question,this.options,this.answer,this.explanation);}
class _UnitTile extends StatefulWidget{final _Unit unit;const _UnitTile({required this.unit});@override State<_UnitTile> createState()=>_UnitTileState();}
class _UnitTileState extends State<_UnitTile>{int? choice;bool checked=false;@override Widget build(BuildContext context){final u=widget.unit;return Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(title:Text(u.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(u.objective),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(u.content),const SizedBox(height:8),Text('Exemple : ${u.example}',style:const TextStyle(fontStyle:FontStyle.italic)),const SizedBox(height:12),Text(u.question,style:const TextStyle(fontWeight:FontWeight.bold)),for(var i=0;i<u.options.length;i++)RadioListTile<int>(dense:true,contentPadding:EdgeInsets.zero,value:i,groupValue:choice,title:Text(u.options[i]),onChanged:checked?null:(v)=>setState(()=>choice=v)),FilledButton.tonal(onPressed:choice==null?null:()=>setState(()=>checked=true),child:const Text('Vérifier ma réponse')),if(checked)Text('${choice==u.answer?'Bonne réponse ! ':'À revoir. Bonne réponse : ${u.options[u.answer]}. '}${u.explanation}',style:TextStyle(fontWeight:FontWeight.w600,color:choice==u.answer?Colors.green.shade800:Theme.of(context).colorScheme.error)),if(checked)TextButton(onPressed:()=>setState((){choice=null;checked=false;}),child:const Text('Recommencer'))]))]));}}
